package testfixture

import (
	"encoding/binary"
)

const (
	NDSTrimmedSize = 0xc000
	DSiTrimmedSize = 0x8c000
)

// NDS returns a generated DS or DSi cartridge layout with uniform FF padding.
func NDS(twl bool) []byte {
	capacity, used, checksum := 0x20000, NDSTrimmedSize, uint16(0xaa32)
	if twl {
		capacity, used, checksum = 0x100000, DSiTrimmedSize, 0x9b02
	}
	data := make([]byte, capacity)
	for i := used; i < len(data); i++ {
		data[i] = 0xff
	}
	copy(data[:12], "SYNTHETIC DS")
	copy(data[0x0c:], "ZZZE01")
	// The logo field uses generated bytes with the documented checksum.
	for i := 0; i < 154; i++ {
		data[0xc0+i] = byte(i*7 + 3)
	}
	data[0x15a], data[0x15b] = 0xd9, 0xe7
	binary.LittleEndian.PutUint16(data[0x15c:], 0xcf56)
	words := map[int]uint32{
		0x20: 0x4000, 0x24: 0x2004000, 0x28: 0x2004000, 0x2c: 0x4000,
		0x30: 0x8000, 0x34: 0x2380000, 0x38: 0x2380000, 0x3c: 0x1000,
		0x40: 0x9000, 0x44: 13, 0x48: 0x9020, 0x4c: 16,
		0x50: 0x9040, 0x54: 32, 0x68: 0x9400, 0x80: NDSTrimmedSize, 0x84: 0x4000,
		0x9000: 8, 0x9004: 0x00010000,
		0x9020: 0xa000, 0x9024: 0xa400, 0x9028: 0xa400, 0x902c: 0xa800,
		0x9044: 0x2010000, 0x9048: 0x400,
	}
	copy(data[0x9008:], []byte{1, 'a', 1, 'b', 0})
	binary.LittleEndian.PutUint16(data[0x9400:], 1)
	if twl {
		data[0x12], data[0x14] = 2, 3
		words[0x90] = 0x00010001
		for at, word := range map[int]uint32{
			0x1c0: 0x83000, 0x1c8: 0x2400000, 0x1cc: 0x4000,
			0x1d0: 0x88000, 0x1d8: 0x2e80000, 0x1dc: 0x2000,
			0x1e0: 0x4000, 0x1e4: 0x8000, 0x1e8: 0x83000, 0x1ec: 0x7000,
			0x1f0: 0xb000, 0x1f4: 0x100, 0x1f8: 0xb100, 0x1fc: 0x80,
			0x200: 0x400, 0x204: 0x20, 0x208: 0x840, 0x210: DSiTrimmedSize,
			0x220: 0x83000, 0x224: 0x4000, 0x228: 0x88000, 0x22c: 0x2000,
			0x230: 0x5a5a5a45, 0x234: 0x00030000,
		} {
			words[at] = word
		}
		data[DSiTrimmedSize-1] = 0x7c
	}
	for at, word := range words {
		binary.LittleEndian.PutUint32(data[at:], word)
	}
	data[0xa7ff] = 0x55
	// Independently calculated CRC-16 values for these two headers.
	binary.LittleEndian.PutUint16(data[0x15e:], checksum)
	return data
}
